function formatEnumLabel(value) {
  if (!value) return '—';
  return value.replace(/_/g, ' ');
}

function formatMedecinName(medecin) {
  if (!medecin) return '—';
  return `${medecin.nom ?? ''} ${medecin.prenom ?? ''}`.trim().toUpperCase();
}

function formatDate(value) {
  if (!value) return '—';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleDateString('fr-FR');
}

function calculateDaysRemaining(dateStr) {
  if (!dateStr) return '—';
  const target = new Date(dateStr);
  if (isNaN(target.getTime())) return '—';
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  target.setHours(0, 0, 0, 0);
  const diffTime = target - today;
  const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));
  if (diffDays > 0) return `${diffDays} j`;
  if (diffDays === 0) return "Aujourd'hui";
  return `Échéance dépassée (${Math.abs(diffDays)} j)`;
}

function getVisitDateLabel(action) {
  return action?.etatAction === 'REALISEE' ? 'Date de réalisation' : 'Date planifiée';
}

function getVisitTimingLabel(action) {
  if (action?.etatAction === 'REALISEE') {
    const date = new Date(action.dateVisite);
    if (Number.isNaN(date.getTime())) return 'Réalisée';
    const today = new Date();
    date.setHours(0, 0, 0, 0);
    today.setHours(0, 0, 0, 0);
    const diffDays = Math.round((today - date) / (1000 * 60 * 60 * 24));
    if (diffDays === 0) return "Réalisée aujourd'hui";
    return `Réalisée il y a ${diffDays} j`;
  }
  return calculateDaysRemaining(action?.dateVisite);
}

/** Fréquence de visite attendue selon le segment (même logique que le backend) */
function calculateFrequenceJours(segment) {
  if (!segment) return null;
  switch (segment.trim().toUpperCase()) {
    case 'A': return 7;
    case 'B': return 10;
    case 'C': return 15;
    case 'D': return 30;
    default:  return null;
  }
}

function getActionDescription(action, medecin) {
  const statut = (action?.statut || medecin?.statut || '').toUpperCase();
  if (statut === 'SURVEILLANCE' || statut === 'SILENCE_CRITIQUE' || statut === 'RETENTION') {
    return 'Silence stratégique ou baisse d\'activité confirmée : médecin à potentiel élevé nécessitant une visite prioritaire.';
  }
  if (statut === 'PROGRESSION') {
    return 'Médecin en nette progression commerciale (+20 % CA) : effectuer une visite de suivi pour pérenniser l\'activité.';
  }
  if (statut === 'ONBOARDING') {
    return 'Médecin nouvellement intégré : réaliser la première visite de présentation et d\'accompagnement.';
  }
  return 'Maintenir le rythme d\'échanges commercial régulier avec le médecin.';
}

function formatExplanationScore(value) {
  return value == null || Number.isNaN(Number(value))
    ? '—'
    : Number(value).toLocaleString('fr-FR', { maximumFractionDigits: 2 });
}

function formatPotentialSource(source) {
  if (source === 'NOTE_TERRAIN') return 'note terrain';
  if (source === 'INPUT_PROFIL') return 'input profil';
  return 'défaut 3/5';
}

function formatWeightedExplanation(value, weight) {
  return value == null ? '—' : formatExplanationScore(Number(value) * weight);
}

