  const { token } = useAuth();
  const [filters, setFilters] = useState(FILTER_DEFAULTS);
  const [pageData, setPageData] = useState(null);

  // Selection & View Mode state: 'table' or 'detail'
  const [selectedAction, setSelectedAction] = useState(null);
  const [medecinEvolution, setMedecinEvolution] = useState([]);
  const [loadingEvolution, setLoadingEvolution] = useState(false);
  const [isExplanationOpen, setIsExplanationOpen] = useState(false);
  const [openActionBlocks, setOpenActionBlocks] = useState({ valeur: true, action: true, urgence: true, silence: true, etat: true });
  const toggleActionBlock = (block) => setOpenActionBlocks((current) => ({ ...current, [block]: !current[block] }));
  const [viewMode, setViewMode] = useState('table');

  // Sauvegarde de la position exacte de scroll avant sélection
  const lastScrollPosition = useRef(0);
  const lastSelectedActionIdRef = useRef(null);

  // Onglets principaux: 'VACTIS' (Actions moteur VACTIS) ou 'LIBRES' (Visites commerciales libres)
  const [activeTab, setActiveTab] = useState('VACTIS');

  // Modals & Drawer State
  const [isSaisieRetourOpen, setIsSaisieRetourOpen] = useState(false);
  const [actionToSubmit, setActionToSubmit] = useState(null);

  const [isVisiteLibreOpen, setIsVisiteLibreOpen] = useState(false);

  const [isDrawerOpen, setIsDrawerOpen] = useState(false);
  const [drawerMedecinId, setDrawerMedecinId] = useState(null);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [retourSuccessMessage, setRetourSuccessMessage] = useState('');
  const [retourErrorMessage, setRetourErrorMessage] = useState('');

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Reservation handler
  const handleReserverAction = async (actionId, e) => {
    if (e) e.stopPropagation();
    if (!token) return;
    try {
      await reserverActionApi(token, actionId);
      loadActions();
    } catch (err) {
      alert(err.message || 'Impossible de réserver cette action');
    }
  };

  // Open Saisie Retour modal
  const handleOpenSaisieRetour = (action, e) => {
    if (e) e.stopPropagation();
    setRetourErrorMessage('');
    setActionToSubmit(action);
    setIsSaisieRetourOpen(true);
  };

  // Submit Saisie Retour
  const handleSubmitRetour = async (payload) => {
    if (!token || !actionToSubmit) return;
    setIsSubmitting(true);
    setRetourSuccessMessage('');
    setRetourErrorMessage('');
    try {
      const savedAction = await soumettreRetourTerrainApi(token, actionToSubmit.id, payload);
      if (payload.qualification === 'RECLAMATION') {
        const claimId = savedAction?.reclamationId;
        setRetourSuccessMessage(
          claimId
            ? `Réclamation #${claimId} créée. Elle est disponible dans l’interface Réclamations.`
            : 'Réclamation créée. Elle est disponible dans l’interface Réclamations.'
        );
      }
      setIsSaisieRetourOpen(false);
      setActionToSubmit(null);
      loadActions();
    } catch (err) {
      setRetourErrorMessage(err.message || 'Impossible d’enregistrer le retour terrain. Vérifiez les informations et réessayez.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const [visitesLibresList, setVisitesLibresList] = useState([]);
  const [medecinsList, setMedecinsList] = useState([]);
  const [loadingVisitesLibres, setLoadingVisitesLibres] = useState(false);

  const loadVisitesLibres = useCallback(async () => {
    if (!token) return;
    setLoadingVisitesLibres(true);
    try {
      const list = await getVisitesLibresApi(token);
      setVisitesLibresList(list || []);
    } catch (err) {
      console.error('Erreur chargement visites libres', err);
    } finally {
      setLoadingVisitesLibres(false);
    }
  }, [token]);

